function validate([formula]) {
  if (typeof formula !== 'string' || formula.length < 1 || formula.length > 1000) return 'formula needs 1 to 1000 characters.';
  if (!/^[A-Za-z0-9()]+$/.test(formula)) return 'formula may only use letters, digits and parentheses.';
  const tokens = formula.match(/[A-Z][a-z]*|[()]|[0-9]+/g) || [];
  if (tokens.join('') !== formula) return 'Each element name must start with an uppercase letter.';
  const stack = [new Map()];
  for (let t = 0; t < tokens.length; t++) {
    const token = tokens[t];
    const next = tokens[t + 1];
    const hasCount = next !== undefined && /^[0-9]/.test(next);
    if (hasCount && next[0] === '0') return 'Counts are positive and have no leading zeros.';
    if (/^[0-9]/.test(token)) {
      const before = tokens[t - 1];
      if (before === undefined || before === '(' || /^[0-9]/.test(before)) return 'A count must follow an element or a closing parenthesis.';
      continue;
    }
    if (token === '(') {
      if (next === ')') return 'Parentheses cannot be empty.';
      stack.push(new Map());
      continue;
    }
    const times = hasCount ? Number(next) : 1;
    if (token === ')') {
      if (stack.length === 1) return 'Parentheses must be balanced.';
      const inner = stack.pop();
      const outer = stack[stack.length - 1];
      for (const [name, c] of inner) outer.set(name, (outer.get(name) || 0) + c * times);
      continue;
    }
    if (hasCount && times < 2) return 'An element count is written only when it is 2 or more.';
    const top = stack[stack.length - 1];
    top.set(token, (top.get(token) || 0) + times);
  }
  if (stack.length !== 1) return 'Parentheses must be balanced.';
  for (const total of stack[0].values()) if (total > 2147483647) return 'Every total must fit in a signed 32-bit integer.';
  return null;
}

