function countOfAtoms(formula) {
  // Recursive descent: parse() reads a formula until a ')' or the end and returns its atom counts.
  let pos = 0;
  const readNumber = () => {
    let digits = '';
    while (pos < formula.length && /[0-9]/.test(formula[pos])) digits += formula[pos++];
    return digits === '' ? 1 : parseInt(digits, 10);
  };
  const parse = () => {
    const counts = Object.create(null);
    while (pos < formula.length && formula[pos] !== ')') {
      if (formula[pos] === '(') {
        pos++;
        const inner = parse();
        pos++;
        const times = readNumber();
        for (const key in inner) counts[key] = (counts[key] || 0) + inner[key] * times;
      } else {
        const match = /^[A-Z][a-z]*/.exec(formula.slice(pos))[0];
        pos += match.length;
        counts[match] = (counts[match] || 0) + readNumber();
      }
    }
    return counts;
  };
  const all = parse();
  const keys = Object.keys(all);
  keys.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return keys.map(key => (all[key] === 1 ? key : key + String(all[key]))).join('');
}

