function generate(rand, size) {
  const large = size === 'large';
  const pool = large
    ? ['H', 'He', 'Hg', 'Li', 'Be', 'B', 'C', 'N', 'O', 'F', 'Ne', 'Na', 'Mg', 'Al', 'Si', 'P', 'S', 'Cl', 'Ar', 'K', 'Ca', 'Fe', 'Cu', 'Zn', 'Ag', 'Au', 'U', 'Xe']
    : ['H', 'He', 'O', 'B', 'Be', 'N', 'C'];
  const pick = n => Math.floor(rand() * n);
  const elementMax = large ? 200 : 12;
  const groupMax = large ? 9 : 4;
  const maxDepth = large ? 4 : 2;
  // build returns a formula's text together with its atom totals, so the generator never needs a parser.
  const build = depth => {
    let text = '';
    const totals = new Map();
    const parts = 1 + pick(large ? 5 : 3);
    for (let p = 0; p < parts; p++) {
      if (depth < maxDepth && rand() < 0.35) {
        const [inner, innerTotals] = build(depth + 1);
        const k = rand() < 0.3 ? 1 : 2 + pick(groupMax - 1);
        text += '(' + inner + ')' + (k > 1 ? k : '');
        for (const [name, c] of innerTotals) totals.set(name, (totals.get(name) || 0) + c * k);
      } else {
        const name = pool[pick(pool.length)];
        const k = rand() < 0.4 ? 1 : 2 + pick(elementMax - 1);
        text += name + (k > 1 ? k : '');
        totals.set(name, (totals.get(name) || 0) + k);
      }
    }
    return [text, totals];
  };
  for (;;) {
    let formula = '';
    const totals = new Map();
    let misses = 0;
    while (misses < 30) {
      const [piece, pieceTotals] = build(0);
      if (formula.length + piece.length > 1000) { misses++; continue; }
      formula += piece;
      for (const [name, c] of pieceTotals) totals.set(name, (totals.get(name) || 0) + c);
      if (!large) break;
    }
    if (formula.length >= 1 && Math.max(...totals.values()) <= 2147483647) return [formula];
  }
}
